class Solution {
    public int lastStoneWeight(int[] stones) {
        List<Integer> s = new ArrayList<>();
        for (int x : stones) s.add(x);
        while (s.size() > 1) {
            Collections.sort(s);
            int y = s.remove(s.size() - 1), x = s.remove(s.size() - 1);
            if (y > x) s.add(y - x);
        }
        return s.isEmpty() ? 0 : s.get(0);
    }
}

