        PriorityQueue<Integer> heap = new PriorityQueue<>(Collections.reverseOrder());
        long cap = w;
        int next = 0;
        for (int round = 0; round < k; round++) {
            while (next < n && capital[order[next]] <= cap) heap.add(profits[order[next++]]);
            if (heap.isEmpty()) break;
            cap += heap.poll();
        }
        return (int) cap;
    }
}

